function assemble(output: any[], status: string | undefined, incompleteReason: string | undefined, owner: string, keepReasoning: boolean, usage?: UsageReport, id?: string, model?: string): NativeResult {
  let text = "";
  let refused = false;
  const toolCalls: ToolCall[] = [];
  const opaque: any[] = [];
  for (const item of output) {
    if (item?.type === "message") {
      for (const part of item.content ?? []) {
        if (part?.type === "output_text") text += part.text ?? "";
        else if (part?.type === "refusal") { text += part.refusal ?? ""; refused = true; }
      }
    } else if (item?.type === "function_call") {
      if (item.status && item.status !== "completed") continue; // an unfinished call never runs
      toolCalls.push({ id: item.call_id ?? item.id, type: "function", function: { name: item.name, arguments: item.arguments ?? "{}" } });
    } else if (item?.type === "reasoning" && keepReasoning && item.encrypted_content) {
      opaque.push({ type: "reasoning", id: item.id, encrypted_content: item.encrypted_content, summary: item.summary ?? [] });
    }
  }
  let finish: NativeFinish = toolCalls.length ? "tool_calls" : refused ? "refusal" : "stop";
  // A content filter stopping the response is a refusal, not an interrupted stream to retry (PRV-16).
  if (status === "incomplete") finish = incompleteReason === "max_output_tokens" ? "length" : incompleteReason === "content_filter" ? "refusal" : "incomplete";
  const message: ChatMessage = {
    role: "assistant",
    content: text || null,
    ...(toolCalls.length ? { tool_calls: toolCalls } : {}),
    ...(opaque.length ? { provider_state: { owner, items: opaque, digest: stateDigest(opaque) } } : {}),
  };
  return { message, finish, usage, providerRequestId: id, effectiveModel: model, text };
}

export function parseResponsesResponse(data: any, owner: string, keepReasoning: boolean): NativeResult {
  if (!data || !Array.isArray(data.output)) throw new ProviderStreamError("Responses payload has no output array", undefined, "", true);
  if (data.status === "failed") throw new ProviderStreamError(`Response failed: ${data.error?.message ?? "unknown error"}`, data.error?.code, "");
  return assemble(data.output, data.status, data.incomplete_details?.reason, owner, keepReasoning, usageOf(data.usage), data.id, data.model);
}

export function responsesStreamParser(owner: string, keepReasoning: boolean, onToken?: (t: string) => void): StreamParser {
  const done: any[] = [];
  let final: any;
  let text = "";
  return {
    text: () => text,
    event(_name, ev) {
      switch (ev?.type) {
        case "response.output_text.delta":
          text += ev.delta ?? "";
          if (ev.delta) onToken?.(ev.delta);
          return;
        case "response.output_item.done":
          if (ev.item) done[ev.output_index ?? done.length] = ev.item;
          return;
        case "response.completed":
        case "response.incomplete":
          final = ev.response ?? {};
          return;
        case "response.failed":
          throw new ProviderStreamError(`Response failed: ${ev.response?.error?.message ?? "unknown error"}`, ev.response?.error?.code, text);
        case "error":
          throw new ProviderStreamError(`Provider error frame mid-stream: ${ev.message ?? ev.error?.message ?? JSON.stringify(ev)}`, ev.code ?? ev.error?.code, text);
        default:
          return;
      }
    },
    result() {
      if (!final) return { message: { role: "assistant", content: text || null }, finish: "incomplete", text };
      const output = Array.isArray(final.output) && final.output.length ? final.output : done.filter(Boolean);
      return assemble(output, final.status, final.incomplete_details?.reason, owner, keepReasoning, usageOf(final.usage), final.id, final.model);
    },
  };
}
  }

  async chatCompletion(
    messages: ChatMessage[],
    tools: ToolDefinition[],
    requestId: string = randomUUID(),
    signal?: AbortSignal,
    /** Receipt role override for auxiliary calls (e.g. "compaction"). */
    purpose?: string,
  ): Promise<ChatMessage> {
    await this.reverifyExpiredKind(signal);
    const response = await this.withReceipt(requestId, purpose, () =>
      this.withOAuthRetry(this.endpoint, requestId, () => this.withParameterRetry(() => this.chatCompletionOnce(messages, tools, requestId, signal))),
    );
    return this.askAgainForNativeCall(response, messages, tools, signal);
  }

  /**
   * A server that answered a tool request with the call as reply text (never executed, REQ-AGT-112) is asked again, at
   * most twice, and only a native call from an answer is used:
   * 1. with the reply and a note that text is not a call, `tool_choice` unchanged: a model that was only quoting JSON
   *    just answers, one that meant a call makes it natively;
   * 2. only if it wrote the call as text again after that note, with `tool_choice: required`.
   * The retry turns exist only in these requests, never in the returned history. The original reply stands whenever a
   * retry fails (an operator abort still propagates) or yields no native call; a prose answer to the note replaces it.
   * Token usage and cost of every request are summed into the last-usage report.
   */
  private async askAgainForNativeCall(response: ChatMessage, messages: ChatMessage[], tools: ToolDefinition[], signal?: AbortSignal, onToken?: StreamTokenCallback): Promise<ChatMessage> {
    if (this.conn.protocol !== "openai-chat" || this.conn.streamOnly || this.askedAgain.has(response) || !isContentCallReply(response, tools, messages)) return response;
    this.askedAgain.add(response);
    const corrected: ChatMessage[] = [...messages, { role: "assistant", content: response.content }, { role: "user", content: CONTENT_CALL_NOTE }];
    const usages = [this.lastUsageReport];
    const ask = async (toolChoice: "auto" | "required"): Promise<ChatMessage | undefined> => {
      const requestId = randomUUID();
      try {
        const answer = await this.withReceipt(requestId, "tool-call-retry", () =>
          this.withOAuthRetry(this.endpoint, requestId, () => this.withParameterRetry(() => this.chatCompletionOnce(corrected, tools, requestId, signal, toolChoice))),
        );
        usages.push(this.lastUsageReport);
        return answer;
      } catch (err) {
        if (signal?.aborted || (err instanceof InferenceError && err.kind === "aborted")) throw err;
        this.emitDiagnostic("error", pc.dim(`[nexus] Asking ${this.conn.label} again for a native tool call failed (${err instanceof Error ? err.message : String(err)}); keeping its first reply.`));
        return undefined;
      }
    };
    const finish = (message: ChatMessage): ChatMessage => {
      this.lastUsageReport = sumUsage(usages);
      return message;
    };
    this.emitDiagnostic("error", pc.dim(`[nexus] ${this.conn.label} answered a tool request with the call as text; telling it so and asking again.`));
    const noted = await ask("auto");
    if (!noted) return finish(response);
    if (noted.tool_calls?.length) return finish({ ...noted, toolCallSource: "feedback" });
    if (!isContentCallReply(noted, tools, messages)) {
      if (typeof noted.content !== "string" || !noted.content.trim()) return finish(response);
      onToken?.(`\n\n${noted.content}`);
      return finish(noted);
    }
    this.emitDiagnostic("error", pc.dim(`[nexus] ${this.conn.label} wrote the call as text again; asking once more with tool_choice=required.`));
    const forced = await ask("required");
    return finish(forced?.tool_calls?.length ? { ...forced, toolCallSource: "required" } : response);
  }

  private async chatCompletionOnce(messages: ChatMessage[], tools: ToolDefinition[], requestId: string, signal?: AbortSignal, toolChoice: "auto" | "required" = "auto"): Promise<ChatMessage> {
    if (this.conn.protocol !== "openai-chat") return this.nativeCompletion(messages, tools, undefined, requestId, signal, this.conn.streamOnly);
    if (this.conn.streamOnly) return this.chatCompletionStreamOnce(messages, tools, undefined, requestId, signal);
    return this.executeWithFailover("chatCompletion", async (currentEp) => {
      if (signal?.aborted) throw abortedError(requestId);
      const url = `${currentEp}/chat/completions`;
      await this.prepareCredential(currentEp, requestId);
      this.preflight(currentEp, requestId, JSON.stringify(messages).length + JSON.stringify(tools).length);

      // 1. Egress Interception & Quarantine (DISC-001..003, CTX-006, FAIL-003)
      const egressEvaluation = this.boundary.evaluateEgress(
        messages,
        currentEp,
        {
          taskId: this.taskId,
          sessionId: this.sessionId,
          sourceBoundary: "HOST_LOCAL",
        }
      );

      if (!egressEvaluation.allowed) {
        throw egressDenied(
          egressEvaluation.reason || `Egress to endpoint '${currentEp}' denied by InformationFlowBoundary [FAIL-003].`
        );
      }

      const outboundMessages: ChatMessage[] = this.sanitizeHistory(egressEvaluation.sanitizedPayload || messages);

      let outboundTools = tools;
      if (tools.length > 0) {
        const toolsEgress = this.boundary.evaluateEgress(
          tools,
          currentEp,
          {
            taskId: this.taskId,
            sessionId: this.sessionId,
            sourceBoundary: "HOST_LOCAL",
          }
        );
        if (!toolsEgress.allowed) {
          throw egressDenied(
            toolsEgress.reason || `Egress of tools to endpoint '${currentEp}' denied by InformationFlowBoundary [FAIL-003].`
          );
        }
        outboundTools = toolsEgress.sanitizedPayload || tools;
      }
      outboundTools = adaptToolDefinitionsForServer(LocalLlmClient.serverKindCache.get(this.kindKey(currentEp)) ?? "unknown", outboundTools);

      const payload: any = {
        model: this.model,
        messages: outboundMessages.map((m) => ({
          role: m.role,
          content: m.content ?? null,
          ...(m.tool_calls ? { tool_calls: m.tool_calls } : {}),
          ...(m.tool_call_id ? { tool_call_id: m.tool_call_id } : {}),
          ...(m.name ? { name: m.name } : {}),
        })),
        temperature: this.temperature,
      };
      // The same output allowance as a streamed request (PRV-09: the empty-stream re-request used to be uncapped).
      if (!this.conn.providerId) payload.max_tokens = this.maxOutputTokens;

      if (outboundTools.length > 0) {
        payload.tools = outboundTools;
        payload.tool_choice = toolChoice;
      }
      if (this.conn.usage === "openrouter") payload.usage = { include: true };
      this.omitUnsupported(payload);
      this.applyToolGrammar(currentEp, requestId, payload, outboundTools);

      const watchdog = this.createWatchdog(signal, currentEp);
      let res: Response;
      let data: ChatCompletionResponse;
      try {
        res = await this.fetchResendingStale(url, {
          method: "POST",
          headers: {
            "Content-Type": "application/json",
            ...this.authorization(url),
            ...this.providerHeaders(messages),
            "X-Request-ID": requestId,
            ...this.routingHeaders(currentEp),
          },
          body: JSON.stringify(payload),
          signal: watchdog.signal,
          ...this.fetchPolicy(),
        });

        if (res.status === 401 && this.reloadAuthToken(url)) {
          watchdog.done();
          await this.reverifyExpiredKind(signal);
          return this.chatCompletionOnce(messages, tools, requestId, signal, toolChoice);
        }

        if (!res.ok) {
          const errText = await res.text();
          throw this.httpError(res.status, errText, requestId, res.headers);
        }
        data = (await res.json()) as ChatCompletionResponse;
      } catch (err: any) {
        watchdog.done();
        throw classifyTransportError(err, signal, requestId, "connect");
      } finally {
        watchdog.done();
      }
      const executions = this.pending?.executions;
      this.pending = {
        usage: chatUsage(data.usage),
        providerRequestId: data.id,
        effectiveModel: (data as any).model,
        endpoint: currentEp,
        ...(executions !== undefined ? { executions } : {}),
      };
      if (!data.choices || data.choices.length === 0) {
        throw new InferenceError("protocol_error", "provider", "Model returned empty choices array", { requestId, failoverEligible: false });
      }

      const choice = data.choices[0] as { message: ChatMessage; finish_reason?: string };
      if (choice.message?.tool_calls && Array.isArray(choice.message.tool_calls)) {
        for (const tc of choice.message.tool_calls) {
          if (tc.function && typeof tc.function.arguments === "object" && tc.function.arguments !== null) {
            tc.function.arguments = JSON.stringify(tc.function.arguments);
          }
        }
      }
      if (this.conn.providerId && choice.finish_reason === "error") {
        throw new InferenceError("provider_error_frame", "provider", "Provider ended the response with finish_reason=error.", { requestId, partialText: typeof choice.message?.content === "string" ? choice.message.content : "" });
      }
      if (choice.finish_reason === "length") {
        throw new InferenceError(
          "output_truncated",
          "client",
          choice.message.tool_calls?.length
            ? "Model output was truncated (finish_reason=length) inside a tool call; refusing to run partial arguments."
            : "Model output was truncated (finish_reason=length); refusing to treat it as a complete answer.",
          { requestId, partialText: typeof choice.message.content === "string" ? choice.message.content : "", failoverEligible: false, truncatedCalls: truncatedCalls(choice.message.tool_calls ?? []) },
        );
      }
      return choice.message;
    });
  }

  /**
   * Real-time SSE token streaming for typewriter terminal output (matching Codex / Claude Code)
   */
  async chatCompletionStream(
    messages: ChatMessage[],
    tools: ToolDefinition[],
    onToken?: StreamTokenCallback,
    requestId: string = randomUUID(),
    signal?: AbortSignal,
  ): Promise<ChatMessage> {
    await this.reverifyExpiredKind(signal);
    const response = await this.withReceipt(requestId, undefined, () =>
      this.withOAuthRetry(this.endpoint, requestId, () =>
        this.withParameterRetry(() => this.chatCompletionStreamOnce(messages, tools, onToken, requestId, signal)),
      ),
    );
    return this.askAgainForNativeCall(response, messages, tools, signal, onToken);
  }

  /**
   * The chat request body exactly as it leaves for `currentEp` (openai-chat protocol): egress quarantine and history
   * sanitization applied to messages and tools, model, temperature, tools and tool_choice, the output allowance
   * (max_tokens on local endpoints) and streaming options. Inference and request counting both send this body, so a
   * count is of the request that is actually sent. Throws when the information-flow boundary denies the egress.
   */
  private outboundChatBody(currentEp: string, requestId: string, messages: ChatMessage[], tools: ToolDefinition[]): any {
    // 1. Egress Interception & Quarantine (DISC-001..003, CTX-006, FAIL-003)
    const egressEvaluation = this.boundary.evaluateEgress(
      messages,
      currentEp,
      {
        taskId: this.taskId,
        sessionId: this.sessionId,
        sourceBoundary: "HOST_LOCAL",
      }
    );

    if (!egressEvaluation.allowed) {
      throw egressDenied(
        egressEvaluation.reason || `Egress to endpoint '${currentEp}' denied by InformationFlowBoundary [FAIL-003].`
      );
    }

    const outboundMessages: ChatMessage[] = this.sanitizeHistory(egressEvaluation.sanitizedPayload || messages);

    let outboundTools = tools;
    if (tools.length > 0) {
      const toolsEgress = this.boundary.evaluateEgress(
        tools,
        currentEp,
        {
          taskId: this.taskId,
          sessionId: this.sessionId,
          sourceBoundary: "HOST_LOCAL",
        }
      );
      if (!toolsEgress.allowed) {
        throw egressDenied(
          toolsEgress.reason || `Egress of tools to endpoint '${currentEp}' denied by InformationFlowBoundary [FAIL-003].`
        );
      }
      outboundTools = toolsEgress.sanitizedPayload || tools;
    }
    outboundTools = adaptToolDefinitionsForServer(LocalLlmClient.serverKindCache.get(this.kindKey(currentEp)) ?? "unknown", outboundTools);

    const payload: any = {
      model: this.model,
      messages: outboundMessages.map((m) => ({
        role: m.role,
        content: m.content ?? null,
        ...(m.tool_calls ? { tool_calls: m.tool_calls } : {}),
        ...(m.tool_call_id ? { tool_call_id: m.tool_call_id } : {}),
        ...(m.name ? { name: m.name } : {}),
      })),
      temperature: this.temperature,
      stream: true,
    };

    if (outboundTools.length > 0) {
      payload.tools = outboundTools;
      payload.tool_choice = "auto";
    }
    // Local endpoints: cap a reply at the completion reserve the context budget already assumes, so a runaway
    // generation cannot run for minutes. (Cloud providers differ on the parameter name and are left to their limits.)
    if (!this.conn.providerId) payload.max_tokens = this.maxOutputTokens;
    if (this.conn.usage === "openrouter") payload.usage = { include: true };
    if (this.conn.usage === "openrouter" || this.conn.usage === "stream-options") payload.stream_options = { include_usage: true };
    this.omitUnsupported(payload);
    this.applyToolGrammar(currentEp, requestId, payload, outboundTools);
    return payload;
  }

  private async chatCompletionStreamOnce(
    messages: ChatMessage[],
    tools: ToolDefinition[],
    onToken: StreamTokenCallback | undefined,
    requestId: string,
    signal?: AbortSignal,
  ): Promise<ChatMessage> {
    if (this.conn.protocol !== "openai-chat") return this.nativeCompletion(messages, tools, onToken, requestId, signal, true);
    return this.executeWithFailover("chatCompletionStream", async (currentEp) => {
      if (signal?.aborted) throw abortedError(requestId);
      const url = `${currentEp}/chat/completions`;
      await this.prepareCredential(currentEp, requestId);
      this.preflight(currentEp, requestId, JSON.stringify(messages).length + JSON.stringify(tools).length);

      const payload = this.outboundChatBody(currentEp, requestId, messages, tools);

      const watchdog = this.createWatchdog(signal, currentEp, true);
      let res: Response;
      try {
        res = await this.fetchResendingStale(url, {
          method: "POST",
          headers: {
            "Content-Type": "application/json",
            ...this.authorization(url),
            ...this.providerHeaders(messages),
            "X-Request-ID": requestId,
            ...this.routingHeaders(currentEp),
          },
          body: JSON.stringify(payload),
          signal: watchdog.signal,
          ...this.fetchPolicy(),
        });
      } catch (err: any) {
        watchdog.done();
        // A resend happens only inside fetchResendingStale (stale keep-alive, before any response byte); any other
        // rejection goes to the agent loop.
        throw classifyTransportError(err, signal, requestId, "connect");
      }

      if (res.status === 401 && this.reloadAuthToken(url)) {
        watchdog.done();
        await this.reverifyExpiredKind(signal);
        return this.chatCompletionStreamOnce(messages, tools, onToken, requestId, signal);
      }

      if (!res.ok || !res.body) {
        try {
          const errText = await res.text();
          throw this.httpError(res.status, errText, requestId, res.headers);
        } catch (err: any) {
          if (err instanceof InferenceError) throw err;
          throw classifyTransportError(err, signal, requestId, "stream");
        } finally {
          watchdog.done();
        }
      }

      this.lastAdmission = parseAdmissionHeaders((name) => res.headers.get(name));
      let fullContent = "";
      let reasoningContent = "";
      let hasOutput = false;
      let finishReason: string | undefined;
      let sawDone = false;
      this.pending = { endpoint: currentEp, executions: this.pending?.executions };
      const toolCallsMap: Map<number, { id: string; name: string; args: string }> = new Map();

      const reader = res.body.getReader();
      const decoder = new TextDecoder("utf-8");
      let buffer = "";

      // Positive completion evidence for this protocol: a chunk carrying a non-null finish_reason, or the
      // terminal `data: [DONE]` event. Absence of both means the stream ended early.
      const handleLine = (line: string): void => {
        const trimmed = line.trim();
        if (!trimmed || trimmed.startsWith(":")) return;
        if (trimmed === "data: [DONE]" || trimmed === "data:[DONE]") {
          sawDone = true;
          return;
        }
        if (!trimmed.startsWith("data:") && !trimmed.startsWith("data: ")) return;
        const payload = trimmed.startsWith("data: ") ? trimmed.slice(6) : trimmed.slice(5);
        let chunk: any;
        try {
          chunk = JSON.parse(payload);
        } catch {
          throw new InferenceError("malformed_event", "provider", `Malformed stream event: ${trimmed.slice(0, 120)}`, {
            requestId,
            partialText: fullContent,
            failoverEligible: false,
          });
        }
        if (chunk && typeof chunk === "object" && chunk.error) {
          const em = typeof chunk.error === "string" ? chunk.error : chunk.error.message || JSON.stringify(chunk.error);
          const hints = providerHints(undefined, JSON.stringify({ error: chunk.error }));
          // The request was admitted. Only an explicit pre-generation code proves the model never ran it.
          if (hints.errorCode === "pre_generation") {
            throw new InferenceError("provider_error_frame", "provider", `Provider error frame mid-stream: ${boundedProviderText(em)}`, {
              requestId,
              partialText: fullContent,
              hints,
              condition: "TEMPORARILY_UNAVAILABLE",
              execution: hasOutput ? "UNKNOWN" : "NOT_EXECUTED",
            });
          }
          const classifiedCode = hints.errorCode && CLASSIFIED_STREAM_ERRORS.has(hints.errorCode);
          throw this.fromStreamError(new ProviderStreamError(em, classifiedCode ? hints.errorCode : hints.errorType ?? hints.errorCode, fullContent), requestId, hints, hasOutput);
        }
        if (this.pending && chunk && typeof chunk === "object") {
          if (chunk.usage) this.pending.usage = chatUsage(chunk.usage);
          if (typeof chunk.id === "string") this.pending.providerRequestId ??= chunk.id;
          if (typeof chunk.model === "string") this.pending.effectiveModel ??= chunk.model;
        }
        if (chunk.choices?.[0]?.finish_reason) finishReason = chunk.choices[0].finish_reason;
        const delta = chunk.choices?.[0]?.delta;
        if (!delta) return;

        // 1. Text token chunk
        if (delta.content) {
          hasOutput = true;
          fullContent += delta.content;
          if (onToken) {
            onToken(delta.content);
          }
        }
        const reasoningDelta = delta.reasoning_content ?? delta.reasoning;
        if (typeof reasoningDelta === "string") {
          if (reasoningDelta) hasOutput = true;
          reasoningContent += reasoningDelta;
        }

        // 2. Tool call chunks
        if (delta.tool_calls && Array.isArray(delta.tool_calls)) {
          if (delta.tool_calls.length > 0) hasOutput = true;
          for (const tc of delta.tool_calls) {
            // Spec streams give every fragment an index. Some servers (and re-streamed non-streaming
            // responses) omit it; then a fragment that carries an id or a name starts a NEW call, and
            // one with neither continues the latest call. Never fold distinct calls into index 0.
            let idx: number;
            if (typeof tc.index === "number") {
              idx = tc.index;
            } else if (tc.id || tc.function?.name) {
              idx = toolCallsMap.size === 0 ? 0 : Math.max(...toolCallsMap.keys()) + 1;
            } else {
              idx = toolCallsMap.size === 0 ? 0 : Math.max(...toolCallsMap.keys());
            }
            const current = toolCallsMap.get(idx) || { id: "", name: "", args: "" };

            if (tc.id) current.id = tc.id;
            // The name arrives once in spec streams. Some servers repeat it in later deltas, or send it cumulatively;
            // only a genuinely new fragment is appended (PRV-04: a repeated name became "read_fileread_file").
            const fragment = tc.function?.name;
            if (fragment) {
              if (!current.name) current.name = fragment;
              else if (fragment !== current.name) current.name = fragment.startsWith(current.name) ? fragment : current.name + fragment;
            }
            const rawArgs = tc.function?.arguments;
            if (rawArgs !== undefined && rawArgs !== null) {
              if (typeof rawArgs === "object") {
                current.args = JSON.stringify(rawArgs);
              } else {
                current.args += String(rawArgs);
              }
            }

            toolCallsMap.set(idx, current);
          }
        }
      };

      try {
        while (true) {
          const { done, value } = await reader.read();
          if (done) break;
          watchdog.onChunk();

          buffer += decoder.decode(value, { stream: true });
          const lines = buffer.split("\n");
          buffer = lines.pop() || "";
          for (const line of lines) handleLine(line);
        }
        if (buffer.trim()) handleLine(buffer);
      } catch (streamErr: any) {
        try { await reader.cancel(); } catch {}
        const classified = classifyTransportError(streamErr, signal, requestId, "stream", fullContent);
        // A transport error after the terminal event cannot change the (already complete) response.
        const postCompletionTransportError = (finishReason || sawDone) && !(streamErr instanceof InferenceError) && classified.kind !== "aborted";
        if (!postCompletionTransportError) throw classified;
      } finally {
        watchdog.done();
      }

      if (this.conn.providerId && finishReason === "error") {
        throw new InferenceError("provider_error_frame", "provider", "Provider ended the stream with finish_reason=error.", { requestId, partialText: fullContent });
      }
      if (!finishReason && !sawDone) {
        throw new InferenceError(
          "stream_incomplete",
          "transport",
          "Inference stream ended without a finish_reason or [DONE]; response is incomplete.",
          { requestId, partialText: fullContent },
        );
      }

toolUseResult.stdout:
  if (!u || typeof u !== "object") return undefined;
  return {
    ...(num(u.input_tokens) !== undefined ? { inputTokens: u.input_tokens } : {}),
    ...(num(u.output_tokens) !== undefined ? { outputTokens: u.output_tokens } : {}),
    ...(num(u.input_tokens_details?.cached_tokens) !== undefined ? { cachedInputTokens: u.input_tokens_details.cached_tokens } : {}),
    ...(num(u.output_tokens_details?.reasoning_tokens) !== undefined ? { reasoningTokens: u.output_tokens_details.reasoning_tokens } : {}),
  };
}

function assemble(output: any[], status: string | undefined, incompleteReason: string | undefined, owner: string, keepReasoning: boolean, usage?: UsageReport, id?: string, model?: string): NativeResult {
  let text = "";
  let refused = false;
  const toolCalls: ToolCall[] = [];
  const opaque: any[] = [];
  for (const item of output) {
    if (item?.type === "message") {
      for (const part of item.content ?? []) {
        if (part?.type === "output_text") text += part.text ?? "";
        else if (part?.type === "refusal") { text += part.refusal ?? ""; refused = true; }
      }
    } else if (item?.type === "function_call") {
      if (item.status && item.status !== "completed") continue; // an unfinished call never runs
      toolCalls.push({ id: item.call_id ?? item.id, type: "function", function: { name: item.name, arguments: item.arguments ?? "{}" } });
    } else if (item?.type === "reasoning" && keepReasoning && item.encrypted_content) {
      opaque.push({ type: "reasoning", id: item.id, encrypted_content: item.encrypted_content, summary: item.summary ?? [] });
    }
  }
  let finish: NativeFinish = toolCalls.length ? "tool_calls" : refused ? "refusal" : "stop";
  // A content filter stopping the response is a refusal, not an interrupted stream to retry (PRV-16).
  if (status === "incomplete") finish = incompleteReason === "max_output_tokens" ? "length" : incompleteReason === "content_filter" ? "refusal" : "incomplete";
  const message: ChatMessage = {
    role: "assistant",
    content: text || null,
    ...(toolCalls.length ? { tool_calls: toolCalls } : {}),
    ...(opaque.length ? { provider_state: { owner, items: opaque, digest: stateDigest(opaque) } } : {}),
  };
  return { message, finish, usage, providerRequestId: id, effectiveModel: model, text };
}

export function parseResponsesResponse(data: any, owner: string, keepReasoning: boolean): NativeResult {
  if (!data || !Array.isArray(data.output)) throw new ProviderStreamError("Responses payload has no output array", undefined, "", true);
  if (data.status === "failed") throw new ProviderStreamError(`Response failed: ${data.error?.message ?? "unknown error"}`, data.error?.code, "");
  return assemble(data.output, data.status, data.incomplete_details?.reason, owner, keepReasoning, usageOf(data.usage), data.id, data.model);
}

export function responsesStreamParser(owner: string, keepReasoning: boolean, onToken?: (t: string) => void): StreamParser {
  const done: any[] = [];
  let final: any;
  let text = "";
  return {
    text: () => text,
    event(_name, ev) {
      switch (ev?.type) {
        case "response.output_text.delta":
          text += ev.delta ?? "";
          if (ev.delta) onToken?.(ev.delta);
          return;
        case "response.output_item.done":
          if (ev.item) done[ev.output_index ?? done.length] = ev.item;
          return;
        case "response.completed":
        case "response.incomplete":
          final = ev.response ?? {};
          return;
        case "response.failed":
          throw new ProviderStreamError(`Response failed: ${ev.response?.error?.message ?? "unknown error"}`, ev.response?.error?.code, text);
        case "error":
          throw new ProviderStreamError(`Provider error frame mid-stream: ${ev.message ?? ev.error?.message ?? JSON.stringify(ev)}`, ev.code ?? ev.error?.code, text);
        default:
          return;
      }
    },
    result() {
      if (!final) return { message: { role: "assistant", content: text || null }, finish: "incomplete", text };
      const output = Array.isArray(final.output) && final.output.length ? final.output : done.filter(Boolean);
      return assemble(output, final.status, final.incomplete_details?.reason, owner, keepReasoning, usageOf(final.usage), final.id, final.model);
    },
  };
}
  }

  async chatCompletion(
    messages: ChatMessage[],
    tools: ToolDefinition[],
    requestId: string = randomUUID(),
    signal?: AbortSignal,
    /** Receipt role override for auxiliary calls (e.g. "compaction"). */
    purpose?: string,
  ): Promise<ChatMessage> {
    await this.reverifyExpiredKind(signal);
    const response = await this.withReceipt(requestId, purpose, () =>
      this.withOAuthRetry(this.endpoint, requestId, () => this.withParameterRetry(() => this.chatCompletionOnce(messages, tools, requestId, signal))),
    );
    return this.askAgainForNativeCall(response, messages, tools, signal);
  }

  /**
   * A server that answered a tool request with the call as reply text (never executed, REQ-AGT-112) is asked again, at
   * most twice, and only a native call from an answer is used:
   * 1. with the reply and a note that text is not a call, `tool_choice` unchanged: a model that was only quoting JSON
   *    just answers, one that meant a call makes it natively;
   * 2. only if it wrote the call as text again after that note, with `tool_choice: required`.
   * The retry turns exist only in these requests, never in the returned history. The original reply stands whenever a
   * retry fails (an operator abort still propagates) or yields no native call; a prose answer to the note replaces it.
   * Token usage and cost of every request are summed into the last-usage report.
   */
  private async askAgainForNativeCall(response: ChatMessage, messages: ChatMessage[], tools: ToolDefinition[], signal?: AbortSignal, onToken?: StreamTokenCallback): Promise<ChatMessage> {
    if (this.conn.protocol !== "openai-chat" || this.conn.streamOnly || this.askedAgain.has(response) || !isContentCallReply(response, tools, messages)) return response;
    this.askedAgain.add(response);
    const corrected: ChatMessage[] = [...messages, { role: "assistant", content: response.content }, { role: "user", content: CONTENT_CALL_NOTE }];
    const usages = [this.lastUsageReport];
    const ask = async (toolChoice: "auto" | "required"): Promise<ChatMessage | undefined> => {
      const requestId = randomUUID();
      try {
        const answer = await this.withReceipt(requestId, "tool-call-retry", () =>
          this.withOAuthRetry(this.endpoint, requestId, () => this.withParameterRetry(() => this.chatCompletionOnce(corrected, tools, requestId, signal, toolChoice))),
        );
        usages.push(this.lastUsageReport);
        return answer;
      } catch (err) {
        if (signal?.aborted || (err instanceof InferenceError && err.kind === "aborted")) throw err;
        this.emitDiagnostic("error", pc.dim(`[nexus] Asking ${this.conn.label} again for a native tool call failed (${err instanceof Error ? err.message : String(err)}); keeping its first reply.`));
        return undefined;
      }
    };
    const finish = (message: ChatMessage): ChatMessage => {
      this.lastUsageReport = sumUsage(usages);
      return message;
    };
    this.emitDiagnostic("error", pc.dim(`[nexus] ${this.conn.label} answered a tool request with the call as text; telling it so and asking again.`));
    const noted = await ask("auto");
    if (!noted) return finish(response);
    if (noted.tool_calls?.length) return finish({ ...noted, toolCallSource: "feedback" });
    if (!isContentCallReply(noted, tools, messages)) {
      if (typeof noted.content !== "string" || !noted.content.trim()) return finish(response);
      onToken?.(`\n\n${noted.content}`);
      return finish(noted);
    }
    this.emitDiagnostic("error", pc.dim(`[nexus] ${this.conn.label} wrote the call as text again; asking once more with tool_choice=required.`));
    const forced = await ask("required");
    return finish(forced?.tool_calls?.length ? { ...forced, toolCallSource: "required" } : response);
  }

  private async chatCompletionOnce(messages: ChatMessage[], tools: ToolDefinition[], requestId: string, signal?: AbortSignal, toolChoice: "auto" | "required" = "auto"): Promise<ChatMessage> {
    if (this.conn.protocol !== "openai-chat") return this.nativeCompletion(messages, tools, undefined, requestId, signal, this.conn.streamOnly);
    if (this.conn.streamOnly) return this.chatCompletionStreamOnce(messages, tools, undefined, requestId, signal);
    return this.executeWithFailover("chatCompletion", async (currentEp) => {
      if (signal?.aborted) throw abortedError(requestId);
      const url = `${currentEp}/chat/completions`;
      await this.prepareCredential(currentEp, requestId);
      this.preflight(currentEp, requestId, JSON.stringify(messages).length + JSON.stringify(tools).length);

      // 1. Egress Interception & Quarantine (DISC-001..003, CTX-006, FAIL-003)
      const egressEvaluation = this.boundary.evaluateEgress(
        messages,
        currentEp,
        {
          taskId: this.taskId,
          sessionId: this.sessionId,
          sourceBoundary: "HOST_LOCAL",
        }
      );

      if (!egressEvaluation.allowed) {
        throw egressDenied(
          egressEvaluation.reason || `Egress to endpoint '${currentEp}' denied by InformationFlowBoundary [FAIL-003].`
        );
      }

      const outboundMessages: ChatMessage[] = this.sanitizeHistory(egressEvaluation.sanitizedPayload || messages);

      let outboundTools = tools;
      if (tools.length > 0) {
        const toolsEgress = this.boundary.evaluateEgress(
          tools,
          currentEp,
          {
            taskId: this.taskId,
            sessionId: this.sessionId,
            sourceBoundary: "HOST_LOCAL",
          }
        );
        if (!toolsEgress.allowed) {
          throw egressDenied(
            toolsEgress.reason || `Egress of tools to endpoint '${currentEp}' denied by InformationFlowBoundary [FAIL-003].`
          );
        }
        outboundTools = toolsEgress.sanitizedPayload || tools;
      }
      outboundTools = adaptToolDefinitionsForServer(LocalLlmClient.serverKindCache.get(this.kindKey(currentEp)) ?? "unknown", outboundTools);

      const payload: any = {
        model: this.model,
        messages: outboundMessages.map((m) => ({
          role: m.role,
          content: m.content ?? null,
          ...(m.tool_calls ? { tool_calls: m.tool_calls } : {}),
          ...(m.tool_call_id ? { tool_call_id: m.tool_call_id } : {}),
          ...(m.name ? { name: m.name } : {}),
        })),
        temperature: this.temperature,
      };
      // The same output allowance as a streamed request (PRV-09: the empty-stream re-request used to be uncapped).
      if (!this.conn.providerId) payload.max_tokens = this.maxOutputTokens;

      if (outboundTools.length > 0) {
        payload.tools = outboundTools;
        payload.tool_choice = toolChoice;
      }
      if (this.conn.usage === "openrouter") payload.usage = { include: true };
      this.omitUnsupported(payload);
      this.applyToolGrammar(currentEp, requestId, payload, outboundTools);

      const watchdog = this.createWatchdog(signal, currentEp);
      let res: Response;
      let data: ChatCompletionResponse;
      try {
        res = await this.fetchResendingStale(url, {
          method: "POST",
          headers: {
            "Content-Type": "application/json",
            ...this.authorization(url),
            ...this.providerHeaders(messages),
            "X-Request-ID": requestId,
            ...this.routingHeaders(currentEp),
          },
          body: JSON.stringify(payload),
          signal: watchdog.signal,
          ...this.fetchPolicy(),
        });

        if (res.status === 401 && this.reloadAuthToken(url)) {
          watchdog.done();
          await this.reverifyExpiredKind(signal);
          return this.chatCompletionOnce(messages, tools, requestId, signal, toolChoice);
        }

        if (!res.ok) {
          const errText = await res.text();
          throw this.httpError(res.status, errText, requestId, res.headers);
        }
        data = (await res.json()) as ChatCompletionResponse;
      } catch (err: any) {
        watchdog.done();
        throw classifyTransportError(err, signal, requestId, "connect");
      } finally {
        watchdog.done();
      }
      const executions = this.pending?.executions;
      this.pending = {
        usage: chatUsage(data.usage),
        providerRequestId: data.id,
        effectiveModel: (data as any).model,
        endpoint: currentEp,
        ...(executions !== undefined ? { executions } : {}),
      };
      if (!data.choices || data.choices.length === 0) {
        throw new InferenceError("protocol_error", "provider", "Model returned empty choices array", { requestId, failoverEligible: false });
      }

      const choice = data.choices[0] as { message: ChatMessage; finish_reason?: string };
      if (choice.message?.tool_calls && Array.isArray(choice.message.tool_calls)) {
        for (const tc of choice.message.tool_calls) {
          if (tc.function && typeof tc.function.arguments === "object" && tc.function.arguments !== null) {
            tc.function.arguments = JSON.stringify(tc.function.arguments);
          }
        }
      }
      if (this.conn.providerId && choice.finish_reason === "error") {
        throw new InferenceError("provider_error_frame", "provider", "Provider ended the response with finish_reason=error.", { requestId, partialText: typeof choice.message?.content === "string" ? choice.message.content : "" });
      }
      if (choice.finish_reason === "length") {
        throw new InferenceError(
          "output_truncated",
          "client",
          choice.message.tool_calls?.length
            ? "Model output was truncated (finish_reason=length) inside a tool call; refusing to run partial arguments."
            : "Model output was truncated (finish_reason=length); refusing to treat it as a complete answer.",
          { requestId, partialText: typeof choice.message.content === "string" ? choice.message.content : "", failoverEligible: false, truncatedCalls: truncatedCalls(choice.message.tool_calls ?? []) },
        );
      }
      return choice.message;
    });
  }

  /**
   * Real-time SSE token streaming for typewriter terminal output (matching Codex / Claude Code)
   */
  async chatCompletionStream(
    messages: ChatMessage[],
    tools: ToolDefinition[],
    onToken?: StreamTokenCallback,
    requestId: string = randomUUID(),
    signal?: AbortSignal,
  ): Promise<ChatMessage> {
    await this.reverifyExpiredKind(signal);
    const response = await this.withReceipt(requestId, undefined, () =>
      this.withOAuthRetry(this.endpoint, requestId, () =>
        this.withParameterRetry(() => this.chatCompletionStreamOnce(messages, tools, onToken, requestId, signal)),
      ),
    );
    return this.askAgainForNativeCall(response, messages, tools, signal, onToken);
  }

  /**
   * The chat request body exactly as it leaves for `currentEp` (openai-chat protocol): egress quarantine and history
   * sanitization applied to messages and tools, model, temperature, tools and tool_choice, the output allowance
   * (max_tokens on local endpoints) and streaming options. Inference and request counting both send this body, so a
   * count is of the request that is actually sent. Throws when the information-flow boundary denies the egress.
   */
  private outboundChatBody(currentEp: string, requestId: string, messages: ChatMessage[], tools: ToolDefinition[]): any {
    // 1. Egress Interception & Quarantine (DISC-001..003, CTX-006, FAIL-003)
    const egressEvaluation = this.boundary.evaluateEgress(
      messages,
      currentEp,
      {
        taskId: this.taskId,
        sessionId: this.sessionId,
        sourceBoundary: "HOST_LOCAL",
      }
    );

    if (!egressEvaluation.allowed) {
      throw egressDenied(
        egressEvaluation.reason || `Egress to endpoint '${currentEp}' denied by InformationFlowBoundary [FAIL-003].`
      );
    }

    const outboundMessages: ChatMessage[] = this.sanitizeHistory(egressEvaluation.sanitizedPayload || messages);

    let outboundTools = tools;
    if (tools.length > 0) {
      const toolsEgress = this.boundary.evaluateEgress(
        tools,
        currentEp,
        {
          taskId: this.taskId,
          sessionId: this.sessionId,
          sourceBoundary: "HOST_LOCAL",
        }
      );
      if (!toolsEgress.allowed) {
        throw egressDenied(
          toolsEgress.reason || `Egress of tools to endpoint '${currentEp}' denied by InformationFlowBoundary [FAIL-003].`
        );
      }
      outboundTools = toolsEgress.sanitizedPayload || tools;
    }
    outboundTools = adaptToolDefinitionsForServer(LocalLlmClient.serverKindCache.get(this.kindKey(currentEp)) ?? "unknown", outboundTools);

    const payload: any = {
      model: this.model,
      messages: outboundMessages.map((m) => ({
        role: m.role,
        content: m.content ?? null,
        ...(m.tool_calls ? { tool_calls: m.tool_calls } : {}),
        ...(m.tool_call_id ? { tool_call_id: m.tool_call_id } : {}),
        ...(m.name ? { name: m.name } : {}),
      })),
      temperature: this.temperature,
      stream: true,
    };

    if (outboundTools.length > 0) {
      payload.tools = outboundTools;
      payload.tool_choice = "auto";
    }
    // Local endpoints: cap a reply at the completion reserve the context budget already assumes, so a runaway
    // generation cannot run for minutes. (Cloud providers differ on the parameter name and are left to their limits.)
    if (!this.conn.providerId) payload.max_tokens = this.maxOutputTokens;
    if (this.conn.usage === "openrouter") payload.usage = { include: true };
    if (this.conn.usage === "openrouter" || this.conn.usage === "stream-options") payload.stream_options = { include_usage: true };
    this.omitUnsupported(payload);
    this.applyToolGrammar(currentEp, requestId, payload, outboundTools);
    return payload;
  }

  private async chatCompletionStreamOnce(
    messages: ChatMessage[],
    tools: ToolDefinition[],
    onToken: StreamTokenCallback | undefined,
    requestId: string,
    signal?: AbortSignal,
  ): Promise<ChatMessage> {
    if (this.conn.protocol !== "openai-chat") return this.nativeCompletion(messages, tools, onToken, requestId, signal, true);
    return this.executeWithFailover("chatCompletionStream", async (currentEp) => {
      if (signal?.aborted) throw abortedError(requestId);
      const url = `${currentEp}/chat/completions`;
      await this.prepareCredential(currentEp, requestId);
      this.preflight(currentEp, requestId, JSON.stringify(messages).length + JSON.stringify(tools).length);

      const payload = this.outboundChatBody(currentEp, requestId, messages, tools);

      const watchdog = this.createWatchdog(signal, currentEp, true);
      let res: Response;
      try {
        res = await this.fetchResendingStale(url, {
          method: "POST",
          headers: {
            "Content-Type": "application/json",
            ...this.authorization(url),
            ...this.providerHeaders(messages),
            "X-Request-ID": requestId,
            ...this.routingHeaders(currentEp),
          },
          body: JSON.stringify(payload),
          signal: watchdog.signal,
          ...this.fetchPolicy(),
        });
      } catch (err: any) {
        watchdog.done();
        // A resend happens only inside fetchResendingStale (stale keep-alive, before any response byte); any other
        // rejection goes to the agent loop.
        throw classifyTransportError(err, signal, requestId, "connect");
      }

      if (res.status === 401 && this.reloadAuthToken(url)) {
        watchdog.done();
        await this.reverifyExpiredKind(signal);
        return this.chatCompletionStreamOnce(messages, tools, onToken, requestId, signal);
      }

      if (!res.ok || !res.body) {
        try {
          const errText = await res.text();
          throw this.httpError(res.status, errText, requestId, res.headers);
        } catch (err: any) {
          if (err instanceof InferenceError) throw err;
          throw classifyTransportError(err, signal, requestId, "stream");
        } finally {
          watchdog.done();
        }
      }

      this.lastAdmission = parseAdmissionHeaders((name) => res.headers.get(name));
      let fullContent = "";
      let reasoningContent = "";
      let hasOutput = false;
      let finishReason: string | undefined;
      let sawDone = false;
      this.pending = { endpoint: currentEp, executions: this.pending?.executions };
      const toolCallsMap: Map<number, { id: string; name: string; args: string }> = new Map();

      const reader = res.body.getReader();
      const decoder = new TextDecoder("utf-8");
      let buffer = "";

      // Positive completion evidence for this protocol: a chunk carrying a non-null finish_reason, or the
      // terminal `data: [DONE]` event. Absence of both means the stream ended early.
      const handleLine = (line: string): void => {
        const trimmed = line.trim();
        if (!trimmed || trimmed.startsWith(":")) return;
        if (trimmed === "data: [DONE]" || trimmed === "data:[DONE]") {
          sawDone = true;
          return;
        }
        if (!trimmed.startsWith("data:") && !trimmed.startsWith("data: ")) return;
        const payload = trimmed.startsWith("data: ") ? trimmed.slice(6) : trimmed.slice(5);
        let chunk: any;
        try {
          chunk = JSON.parse(payload);
        } catch {
          throw new InferenceError("malformed_event", "provider", `Malformed stream event: ${trimmed.slice(0, 120)}`, {
            requestId,
            partialText: fullContent,
            failoverEligible: false,
          });
        }
        if (chunk && typeof chunk === "object" && chunk.error) {
          const em = typeof chunk.error === "string" ? chunk.error : chunk.error.message || JSON.stringify(chunk.error);
          const hints = providerHints(undefined, JSON.stringify({ error: chunk.error }));
          // The request was admitted. Only an explicit pre-generation code proves the model never ran it.
          if (hints.errorCode === "pre_generation") {
            throw new InferenceError("provider_error_frame", "provider", `Provider error frame mid-stream: ${boundedProviderText(em)}`, {
              requestId,
              partialText: fullContent,
              hints,
              condition: "TEMPORARILY_UNAVAILABLE",
              execution: hasOutput ? "UNKNOWN" : "NOT_EXECUTED",
            });
          }
          const classifiedCode = hints.errorCode && CLASSIFIED_STREAM_ERRORS.has(hints.errorCode);
          throw this.fromStreamError(new ProviderStreamError(em, classifiedCode ? hints.errorCode : hints.errorType ?? hints.errorCode, fullContent), requestId, hints, hasOutput);
        }
        if (this.pending && chunk && typeof chunk === "object") {
          if (chunk.usage) this.pending.usage = chatUsage(chunk.usage);
          if (typeof chunk.id === "string") this.pending.providerRequestId ??= chunk.id;
          if (typeof chunk.model === "string") this.pending.effectiveModel ??= chunk.model;
        }
        if (chunk.choices?.[0]?.finish_reason) finishReason = chunk.choices[0].finish_reason;
        const delta = chunk.choices?.[0]?.delta;
        if (!delta) return;

        // 1. Text token chunk
        if (delta.content) {
          hasOutput = true;
          fullContent += delta.content;
          if (onToken) {
            onToken(delta.content);
          }
        }
        const reasoningDelta = delta.reasoning_content ?? delta.reasoning;
        if (typeof reasoningDelta === "string") {
          if (reasoningDelta) hasOutput = true;
          reasoningContent += reasoningDelta;
        }

        // 2. Tool call chunks
        if (delta.tool_calls && Array.isArray(delta.tool_calls)) {
          if (delta.tool_calls.length > 0) hasOutput = true;
          for (const tc of delta.tool_calls) {
            // Spec streams give every fragment an index. Some servers (and re-streamed non-streaming
            // responses) omit it; then a fragment that carries an id or a name starts a NEW call, and
            // one with neither continues the latest call. Never fold distinct calls into index 0.
            let idx: number;
            if (typeof tc.index === "number") {
              idx = tc.index;
            } else if (tc.id || tc.function?.name) {
              idx = toolCallsMap.size === 0 ? 0 : Math.max(...toolCallsMap.keys()) + 1;
            } else {
              idx = toolCallsMap.size === 0 ? 0 : Math.max(...toolCallsMap.keys());
            }
            const current = toolCallsMap.get(idx) || { id: "", name: "", args: "" };

            if (tc.id) current.id = tc.id;
            // The name arrives once in spec streams. Some servers repeat it in later deltas, or send it cumulatively;
            // only a genuinely new fragment is appended (PRV-04: a repeated name became "read_fileread_file").
            const fragment = tc.function?.name;
            if (fragment) {
              if (!current.name) current.name = fragment;
              else if (fragment !== current.name) current.name = fragment.startsWith(current.name) ? fragment : current.name + fragment;
            }
            const rawArgs = tc.function?.arguments;
            if (rawArgs !== undefined && rawArgs !== null) {
              if (typeof rawArgs === "object") {
                current.args = JSON.stringify(rawArgs);
              } else {
                current.args += String(rawArgs);
              }
            }

            toolCallsMap.set(idx, current);
          }
        }
      };

      try {
        while (true) {
          const { done, value } = await reader.read();
          if (done) break;
          watchdog.onChunk();

          buffer += decoder.decode(value, { stream: true });
          const lines = buffer.split("\n");
          buffer = lines.pop() || "";
          for (const line of lines) handleLine(line);
        }
        if (buffer.trim()) handleLine(buffer);
      } catch (streamErr: any) {
        try { await reader.cancel(); } catch {}
        const classified = classifyTransportError(streamErr, signal, requestId, "stream", fullContent);
        // A transport error after the terminal event cannot change the (already complete) response.
        const postCompletionTransportError = (finishReason || sawDone) && !(streamErr instanceof InferenceError) && classified.kind !== "aborted";
        if (!postCompletionTransportError) throw classified;
      } finally {
        watchdog.done();
      }

      if (this.conn.providerId && finishReason === "error") {
        throw new InferenceError("provider_error_frame", "provider", "Provider ended the stream with finish_reason=error.", { requestId, partialText: fullContent });
      }
      if (!finishReason && !sawDone) {
        throw new InferenceError(
          "stream_incomplete",
          "transport",
          "Inference stream ended without a finish_reason or [DONE]; response is incomplete.",
          { requestId, partialText: fullContent },
        );
      }

content.content:
      : t === "authentication_error" || t === "permission_error" ? { condition: "AUTH_FAILURE", execution: "UNKNOWN" }
      : t === "billing_error" || t === "insufficient_quota" ? { condition: "QUOTA_EXHAUSTED", execution: "UNKNOWN" }
      : { condition: "TEMPORARILY_UNAVAILABLE", execution: "UNKNOWN" };
    return new InferenceError("provider_error_frame", "provider", boundedProviderText(e.message), {
      requestId,
      partialText: e.partialText,
      hints: { ...(t ? { errorType: t } : {}), ...hints },
      ...classification,
    });
  }

  /**
   * Anthropic Messages / OpenAI Responses request. The result is used only when the provider's terminal event arrived:
   * an incomplete stream, a truncated output or a provider error yields a typed failure and no tool call runs.
   */
  private async nativeCompletion(
    messages: ChatMessage[],
    tools: ToolDefinition[],
    onToken: StreamTokenCallback | undefined,
    requestId: string,
    signal: AbortSignal | undefined,
    stream: boolean,
  ): Promise<ChatMessage> {
    return this.executeWithFailover(stream ? "chatCompletionStream" : "chatCompletion", async (currentEp) => {
      if (signal?.aborted) throw abortedError(requestId);
      await this.prepareCredential(currentEp, requestId);
      this.preflight(currentEp, requestId, JSON.stringify(messages).length + JSON.stringify(tools).length);
      const outbound = this.egress(messages, tools, currentEp);
      const anthropic = this.conn.protocol === "anthropic-messages";
      const owner = `${this.conn.providerId}:${this.model}`;
      const input: NativeRequestInput = {
        model: this.model,
        messages: outbound.messages,
        tools: outbound.tools,
        temperature: this.temperature,
        maxOutputTokens: this.maxOutputTokens,
        stream,
        owner,
        reasoningEffort: this.reasoningEffort,
        thinkingBudget: this.thinkingBudget,
      };
      const req = anthropic ? buildAnthropicRequest(input) : buildResponsesRequest(input);
      this.omitUnsupported(req.body);
      if (req.droppedState) {
        this.emitDiagnostic("error", pc.dim(`[nexus] ${req.droppedState} earlier assistant turn(s) carry reasoning state owned by another provider/model or altered since capture; it is not replayed to ${owner} (visible text and tool calls are kept).`));
      }
      const url = `${currentEp}${req.path}`;
      this.pending = { endpoint: currentEp };
      const watchdog = this.createWatchdog(signal, currentEp, stream);
      let res: Response;
      try {
        res = await this.fetchResendingStale(url, {
          method: "POST",
          headers: { "Content-Type": "application/json", ...this.authorization(url), ...this.providerHeaders(outbound.messages), "X-Request-ID": requestId },
          body: JSON.stringify(req.body),
          signal: watchdog.signal,
          ...this.fetchPolicy(),
        });
      } catch (err: any) {
        watchdog.done();
        throw classifyTransportError(err, signal, requestId, "connect");
      }
      if (!res.ok || (stream && !res.body)) {
        try {
          const errText = await res.text();
          throw this.httpError(res.status, errText, requestId, res.headers);
        } catch (err: any) {
          if (err instanceof InferenceError) throw err;
